import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.CTeY_0bQ.js";const h=JSON.parse('{"title":"AgentRuntime：引擎对 agent 平台的要求","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/contracts/agent-runtime.md","filePath":"reference/contracts/agent-runtime.md","lastUpdated":null}'),a={name:"reference/contracts/agent-runtime.md"};function r(i,e,n,l,s,u){return d(),o("div",null,[...e[0]||(e[0]=[c('<div><h1 id="agentruntime-引擎对-agent-平台的要求" tabindex="-1">AgentRuntime：引擎对 agent 平台的要求 <a class="header-anchor" href="#agentruntime-引擎对-agent-平台的要求" aria-label="Permalink to &quot;AgentRuntime：引擎对 agent 平台的要求&quot;">​</a></h1><p>引擎（<code>engine/src</code>）只通过 <code>AgentRuntime</code>（<code>engine/src/runtime.ts</code>）与 agent 平台打交道。现有的实现在各平台的适配器里：Paseo（<code>adapters/paseo/paseo-runtime.ts</code>）、DeepSeek Harness（<code>adapters/dsh/dsh-runtime.ts</code>）、摸高（<code>adapters/mogao/mogao-runtime.ts</code>）、命令行（<code>adapters/cli/cli-runtime.ts</code>，已冻结）；测试用 <code>REQ_PIPELINE_FAKE_RUNTIME</code> 指向的假实现（<code>engine/test/fake-runtime.ts</code>）。要让 laoshi 运行在别的 agent 平台上，就是为那个平台写一个适配器和它的 <code>AgentRuntime</code>（见 <a href="./../design/adapter-guide">adapter-guide</a>）。</p><p>本文说明：能力如何按来源分层、每个方法属于哪一级、没有它时现在的行为、以及适配器应该怎么做。<code>runtime.ts</code> 和 <code>platform.ts</code> 里的类型和注释是字段定义的准确来源，本文不重复。</p><h2 id="级别" tabindex="-1">级别 <a class="header-anchor" href="#级别" aria-label="Permalink to &quot;级别&quot;">​</a></h2><ul><li><strong>必需</strong>：没有就不能运行流水线。适配器必须实现。</li><li><strong>可选</strong>：平台没有时由运行时能力层统一返回 <code>null</code>（或按&quot;现状&quot;一栏降级处理）。</li><li><strong>按需</strong>：只有对应功能被使用时才会调用（卡片接单、需求总览、<code>--worktree</code>、联合需求、对话内转达审批）。</li></ul><p>&quot;现状&quot;一栏记录的是引擎今天的真实行为。标了 ⚠ 的是降级不够平滑、适配器作者需要特别注意的地方。</p><h2 id="能力来源与平台插件-adr-0008" tabindex="-1">能力来源与平台插件（ADR 0008） <a class="header-anchor" href="#能力来源与平台插件-adr-0008" aria-label="Permalink to &quot;能力来源与平台插件（ADR 0008）&quot;">​</a></h2><p>按 <a href="./../adr/0008-capability-sources-and-platform-plugin">ADR 0008</a>，除必需方法外，<code>PlatformAdapter.capabilities</code>（<code>engine/src/platform.ts</code>）为每项可选或按需能力声明提供方来源，按以下优先级选用：</p><table tabindex="0"><thead><tr><th>来源</th><th>含义</th><th>典型示例</th></tr></thead><tbody><tr><td><code>platform</code></td><td>平台原生提供（CLI / SDK / 服务端接口）</td><td>Paseo 提供的 worktree、服务管理、定时任务、额度、profile</td></tr><tr><td><code>plugin</code></td><td>laoshi 为该平台写的插件，运行在平台进程内（只提供能力与视图入口，不编排流程）</td><td><code>laoshi-dsh-plugin</code> 提供的对话子 agent、定时任务、审批、工具轨迹、<code>providerStatus</code></td></tr><tr><td><code>builtin</code></td><td>laoshi 内置实现，与平台无关</td><td><code>git worktree</code>、<code>engine/src/builtin/project-services.ts</code>（<code>.laoshi/services.json</code> 受管服务）</td></tr><tr><td><code>none</code>（未声明）</td><td>确实没有该能力，按契约统一降级</td><td>CLI 的定时消息、dsh 现在的额度与 profile</td></tr></tbody></table><ul><li><strong>统一降级（<code>withCapabilities</code>）</strong>：未声明的能力由 <code>engine/src/platform.ts</code> 中的 <code>withCapabilities(runtime, adapter)</code> 在入口处统一降级——只读能力返回 <code>null</code>，定时能力返回 <code>null</code>，按需动作抛出带有平台名称的说明错误；调用点不再各自重写降级分支。</li><li><strong>能力矩阵体检</strong>：<code>laoshi doctor</code> 的「平台能力」一节逐项列出 <code>CAPABILITIES</code> 中的能力及其实际来源；除了契约允许缺失的项外没有 <code>none</code>，即视为达到完整的集成体验。</li><li><strong>worktree 与服务内置替代</strong>：平台没有原生工作区或服务管理时，适配器可复用 <code>engine/src/builtin/</code> 中的 <code>git worktree</code> 与项目服务管理器，对外仍然通过 <code>createWorktree</code> / <code>listServices</code> 等 <code>AgentRuntime</code> 方法暴露。本机后台调度已决定不作为 <code>builtin</code> 实现（见 <a href="./../design/builtin-capabilities">builtin-capabilities</a>）。</li><li><strong>审批策略与边界（ADR 0008 决定 4）</strong>：涉及步骤 agent 审批时，插件或适配器必须严格遵循配置的审批策略（<code>allow</code> / 交给人）；未写进策略的请求一律交给人，不能默认放行，且只处理 laoshi 步骤 agent 的请求，不干预使用者自有会话。</li></ul><h2 id="必需" tabindex="-1">必需 <a class="header-anchor" href="#必需" aria-label="Permalink to &quot;必需&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>要求</th><th>备注</th></tr></thead><tbody><tr><td><code>verifyOrigin(agentId, cwd)</code></td><td>确认发起流水线的会话存在，且工作目录是 <code>cwd</code>；不满足时抛出面向用户的原因</td><td>步骤 agent 要挂在发起会话下，平台给子 agent 的工作目录必须与会话一致（见 ADR 0001）。没有&quot;会话&quot;概念的平台，应在适配器里自行定义&quot;发起者&quot;并让此方法恒通过</td></tr><tr><td><code>startAgent(input)</code></td><td>按 <code>role</code>、<code>prompt</code>、<code>cwd</code>、<code>labels</code>、<code>profile</code> 创建一个步骤 agent；<code>parentAgentId</code> 非空时挂在该会话下；<code>workspaceId</code> 非空时放进该工作区</td><td>返回 <code>StepAgent</code></td></tr><tr><td><code>StepAgent.wait(timeoutMs)</code></td><td>等待当前回合结束，最多 <code>timeoutMs</code>；遇到权限请求时提前返回</td><td>返回值的 <code>status</code> 为 <code>idle</code> / <code>error</code> / <code>permission</code> / <code>timeout</code>；<code>usage</code> 平台不报告时为 <code>null</code></td></tr><tr><td><code>StepAgent.followUp(text)</code></td><td>在同一会话里开始新回合</td><td>用于&quot;结果文件缺失，请补写&quot;或同轮中断后接续</td></tr><tr><td><code>StepAgent.archive()</code></td><td>归档该 agent</td><td></td></tr><tr><td><code>attachAgent(agentId)</code></td><td>恢复（冷接入）之前可能由另一流水线进程启动的步骤会话</td><td>续跑、重新接着等用；当平台/进程不支持冷恢复时，由引擎结合已有结果文件兜底重做该步</td></tr><tr><td><code>notifyAgent(agentId, text)</code></td><td>向已有会话投递一条消息，不打断它</td><td>进展、需要决定的问题、结论都靠它发回会话。⚠ 没有等价能力的平台，至少要写通知文件让使用者看到（或由适配器支持原生通知通道）</td></tr><tr><td><code>interruptAgent(agentId, text)</code></td><td>打断当前回合，改为处理 <code>text</code></td><td>用于停止一个步骤</td></tr><tr><td><code>close()</code></td><td>释放连接</td><td></td></tr></tbody></table><h2 id="可选" tabindex="-1">可选 <a class="header-anchor" href="#可选" aria-label="Permalink to &quot;可选&quot;">​</a></h2><p>未在 <code>PlatformAdapter.capabilities</code> 中声明的能力由 <code>withCapabilities</code> 统一返回 <code>null</code>（<code>cancelSchedule</code> 返回空）：</p><table tabindex="0"><thead><tr><th>方法</th><th>能力键（<code>CAPABILITIES</code>）</th><th>平台没有时 / 现状</th></tr></thead><tbody><tr><td><code>listProfiles()</code>（req-kit 1.x 叫 <code>listPaseoProfiles</code>）</td><td><code>profiles</code></td><td>返回 <code>null</code>。只影响用 <code>platformProfile</code>（旧名 <code>paseoProfile</code>）引用平台档案的配置：解析不了就拒绝启动并说明。只用 <code>provider/model</code> 直配时不调用</td></tr><tr><td><code>listServices(target)</code>、<code>startServices(target, names, timeoutMs)</code>、<code>stopServices(...)</code></td><td><code>services</code></td><td>无原生能力时可用 <code>builtin</code> 项目服务（<code>.laoshi/services.json</code>）；若声明为 <code>none</code>，<code>listServices</code> 返回 <code>null</code>，<code>startServices</code> 抛出说明，验证改用 <code>verify.md</code> 里的手工启动命令</td></tr><tr><td><code>providerQuota(providers)</code></td><td><code>quota</code></td><td>返回 <code>null</code>；额度提醒关闭，不影响运行</td></tr><tr><td><code>recentActivity(agentId, limit)</code></td><td><code>activity</code></td><td>返回 <code>null</code>；查看进度时不附&quot;最近动作&quot;</td></tr><tr><td><code>runningTool(agentId)</code></td><td><code>runningTool</code></td><td>返回 <code>null</code>；关闭&quot;打断搜索大目录命令&quot;（1.13）</td></tr><tr><td><code>toolCalls?(agentId)</code></td><td><code>toolCalls</code></td><td>返回 <code>null</code>；关闭基于工具调用流的事后/实时危险命令拦截（1.14 <code>dangerGuard</code>）</td></tr><tr><td><code>capabilities()</code></td><td><code>toolInfo</code></td><td>返回 <code>null</code>；当作&quot;未知&quot;，不做依赖平台工具或浏览器的假设</td></tr><tr><td><code>providerStatus()</code></td><td><code>providerStatus</code></td><td>返回 <code>null</code>；接单器体检跳过 provider 登录态核对</td></tr><tr><td><code>scheduleMessage(input)</code>、<code>cancelSchedule(id)</code></td><td><code>scheduling</code></td><td>⚠ 声明为 <code>none</code> 时返回 <code>null</code>：流水线内部（等待提醒、自动继续、定时检查、预约验证）不预约；但 <code>launch.ts</code> 的&quot;预约开始&quot;（<code>--at</code>）<strong>直接失败</strong>并提示&quot;到时再启动&quot;（见下文&quot;调度&quot;）</td></tr><tr><td><code>agentDirectory?(agentId)</code></td><td>—</td><td>可选辅助方法，供内置服务从发起会话推导默认工作目录；未知时返回 <code>null</code></td></tr></tbody></table><h2 id="按需" tabindex="-1">按需 <a class="header-anchor" href="#按需" aria-label="Permalink to &quot;按需&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>能力键（<code>CAPABILITIES</code>）</th><th>用在哪里</th><th>备注</th></tr></thead><tbody><tr><td><code>createWorktree(request)</code>、<code>openWorkspace?(directory)</code>、<code>waitForWorkspaceSetup(id, timeoutMs)</code></td><td><code>worktree</code></td><td><code>--worktree</code>（<code>worktree.ts</code>）和联合需求（<code>joint.ts</code>）</td><td>⚠ 未声明时触发硬错误。没有平台原生工作区的适配器可在适配器内接 <code>engine/src/builtin/worktree.ts</code>（<code>git worktree</code>）；<code>waitForWorkspaceSetup</code> 可恒返回 <code>{ status: &quot;none&quot;, error: null }</code></td></tr><tr><td><code>startSessionAgent(input)</code></td><td><code>sessionAgent</code></td><td>从卡片接单（<code>card-cmd.ts</code>）：为需求新开一个顶层会话</td><td>未声明时不能使用卡片接单</td></tr><tr><td><code>scheduleNewAgent(input)</code></td><td><code>scheduleAgent</code></td><td>需求总览的定时发送（<code>digest.ts --schedule</code>）</td><td>未声明时返回 <code>null</code>，该功能关闭</td></tr><tr><td><code>answerPermission(agentId, requestId, approve, reason)</code></td><td>—</td><td><code>laoshi permission &lt;需求&gt; approve|deny</code>（<code>permission-cmd.ts</code>）：平台的审批不能直接在对话界面里回答、需由对话命令转达人的决定时用；<code>requestId</code> 为 <code>null</code> 表示当前等待的那一个</td><td>没有时，审批在平台自己的界面（如 Paseo 界面、dsh 审批 UI 或插件策略）处理</td></tr></tbody></table><p>适配器还可以声明 <code>runsInChat</code>（<code>PlatformAdapter</code>）：平台只在对话的一个轮次内保留对话容器时，引擎不能在后台脱管运行，<code>launch.ts</code> 让它在对话的命令里前景运行，给对话的消息（<code>notifyAgent</code>）写进 <code>chat.log</code> 并显示在命令输出里。状态文件记下运行引擎的主机名（<code>host</code>），另一台机器上记录的进程不算还在运行。</p><h2 id="调度" tabindex="-1">调度 <a class="header-anchor" href="#调度" aria-label="Permalink to &quot;调度&quot;">​</a></h2><p>引擎里所有&quot;以后再做&quot;（预约开始、等待提醒、限流后自动继续、定时检查、预约验证）都表达为：<strong>在某个时间，向发起会话投递一条写明步骤的消息</strong>（ADR 0020）。适配器实现 <code>scheduleMessage</code>（支持 <code>at</code> / <code>cron</code> 及周期任务的 <code>expiresAt</code> 自动终止）时有三种选择：</p><ol><li>平台有等价的定时任务 → 直接映射（Paseo 的做法）。</li><li>平台插件提供定时创建与生命周期管理 → 在插件内调用平台定时接口并在到 <code>expiresAt</code> 时取消（dsh 插件的做法）。</li><li>都做不到 → 不声明 <code>scheduling</code>（经 <code>withCapabilities</code> 返回 <code>null</code>），按上表处理。</li></ol><h2 id="一致性要求" tabindex="-1">一致性要求 <a class="header-anchor" href="#一致性要求" aria-label="Permalink to &quot;一致性要求&quot;">​</a></h2><p>新适配器至少应满足：</p><ul><li>通过 <code>engine/test</code> 中使用 <code>fake-runtime.ts</code> 的编排测试及 <code>engine/test/conformance.ts</code>（<code>runConformance</code>）所覆盖的行为约定（步骤顺序、续跑、重新接着等、结果文件追问、打断）。读 <code>fake-runtime.ts</code> 可以看到引擎对每个方法的真实期望。</li><li><code>StepAgent.wait</code> 返回 <code>permission</code> 时，<code>pendingPermissions</code> 非空且有可读的 <code>title</code>。</li><li>步骤 agent 的创建要保证产物写在 <code>cwd</code> 下（ADR 0001 的问题：有的平台在传了 parent 时会改用 parent 的目录）。</li><li>能力是否支持统一在 <code>PlatformAdapter.capabilities</code> 中声明，交给 <code>withCapabilities</code> 处理，不在核心调用点假定平台特性。</li></ul><h2 id="后续演进预留-暂未改变当前契约" tabindex="-1">后续演进预留（暂未改变当前契约） <a class="header-anchor" href="#后续演进预留-暂未改变当前契约" aria-label="Permalink to &quot;后续演进预留（暂未改变当前契约）&quot;">​</a></h2><p><a href="./../adr/0008-capability-sources-and-platform-plugin">ADR 0008</a> 决定 5 中已经完成了 <code>listProfiles</code> 命名、能力来源声明（<code>PlatformAdapter.capabilities</code> + <code>withCapabilities</code>）与审批策略接入。以下两项作为后续按需演进预留，若将来推进，将按契约变更规则与实现一并提交：</p><ul><li><strong>统一 agent 事件模型</strong>：由核心从事件流推导 <code>wait</code>、<code>recentActivity</code>、<code>runningTool</code>、<code>toolCalls</code> 和用量，适配器只需输出事件流（轮询型平台由适配器将状态变更转为事件）。</li><li><strong>对话通道独立拆层</strong>：把 <code>verifyOrigin</code>、<code>notifyAgent</code>、定时消息等能力拆成可独立组合的&quot;对话通道&quot;，便于实现&quot;平台运行时 + 外部通知通道&quot;等组合（目前摸高/外部 IM 通知仍由 <code>notifiers</code> 与适配器钩子承担）。</li></ul><h2 id="中性化-laoshi-m2a–m2e-已处理" tabindex="-1">中性化（laoshi M2a–M2e 已处理） <a class="header-anchor" href="#中性化-laoshi-m2a–m2e-已处理" aria-label="Permalink to &quot;中性化（laoshi M2a–M2e 已处理）&quot;">​</a></h2><p>req-kit 1.x 里带 Paseo 字样的地方，laoshi 中已改为中性的名称：</p><ul><li>方法与字段：<code>listPaseoProfiles</code> → <code>listProfiles</code>（M2a），<code>capabilities().paseoTools</code> → <code>platformTools</code>（M2e）。<code>ServiceTarget</code>、<code>ManagedService</code> 本来就是中性的名字，只改了注释。</li><li>状态文件字段：<code>originAgentId</code>、<code>worktree.workspaceId</code>、<code>schedules[]</code> 在第 2 版中改名（M2d，见 <code>state.md</code>）；对外契约不变。</li><li>面向使用者的文案和提示词：改用适配器的词汇表（M2e，<code>engine/src/words.ts</code>，见 <a href="./../design/platform-vocabulary">platform-vocabulary</a>）；<code>engine/prompts/paseo-services.md</code> 改名为 <code>managed-services.md</code>。</li><li>会话识别：由适配器声明环境变量（<code>originEnv</code>，M2a）；使用者识别同样由适配器声明（<code>userEnv</code>，如摸高的 <code>AIMAX_USER_NAME</code>，ADR 0007）。</li><li>配置：<code>AgentProfile.paseoProfile</code> → <code>platformProfile</code>，<code>paseoServices</code> → <code>platformServices</code>，旧名继续读取（M2e）；daemon 地址可写在 <code>platform.paseo</code> 中（M2c）。</li></ul><p><code>engine/test/platform.test.ts</code> 检查核心代码和提示词里不出现平台名（有意保留的旧字段名、对外契约字段，在那一行或上一行写明 <code>platform-name:</code> 和原因）。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/laoshi/blob/main/contracts/agent-runtime.md">contracts/agent-runtime.md</a> 生成。<a href="https://github.com/yiyisf/laoshi/edit/main/contracts/agent-runtime.md">在 GitHub 上编辑</a></p>',2)])])}const g=t(a,[["render",r]]);export{h as __pageData,g as default};
